namespace ghidra.app.plugin.core.reloc;

using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.program.model.mem;
using ghidra.program.model.reloc;
using ghidra.program.model.util;
using ghidra.util.classfinder;

public abstract class RelocationFixupHandler : ExtensionPoint {

	/**
	 * Default abstract constructor for an {@link RelocationFixupHandler}.
	 */
	protected RelocationFixupHandler() {
	}

	public abstract bool processRelocation(Program program, Relocation relocation,
			Address oldImageBase, Address newImageBase);

	public abstract bool handlesProgram(Program program);

	protected bool process32BitRelocation(Program program, Relocation relocation,
			Address oldImageBase, Address newImageBase)
    {
		long diff = newImageBase.subtract(oldImageBase);

		Address address = relocation.getAddress();
		Memory memory = program.getMemory();
		int value = memory.getInt(address);
		int newValue = (int) (value + diff);

		InstructionStasher instructionStasher = new InstructionStasher(program, address);

		memory.setInt(address, newValue);

		instructionStasher.restore();

		return true;
	}

	public bool process64BitRelocation(Program program, Relocation relocation,
			Address oldImageBase, Address newImageBase)
    {

		long diff = newImageBase.subtract(oldImageBase);

		Address address = relocation.getAddress();
		Memory memory = program.getMemory();
		long value = memory.getLong(address);
		long newValue = value + diff;

		InstructionStasher instructionStasher = new InstructionStasher(program, address);

		memory.setLong(address, newValue);

		instructionStasher.restore();

		return true;
	}
}
